router.post('/payments/:id/approve', requireAuth, async (req, res) => {
  const actor = req.session.principalId;                 // verified session, not the body
  const { rows } = await db.query(
    `UPDATE payments SET approved_by = $2, status = 'approved'
      WHERE id = $1 AND status = 'pending' AND initiated_by <> $2
      RETURNING id`, [req.params.id, actor]);
  if (rows.length === 0) return res.status(409).json({ error: 'not approvable' });
  res.json({ ok: true });
});
